from collections import deque
from collections.abc import Iterable, Iterator


def chunked[T](items: Iterable[T], size: int) -> Iterator[list[T]]:
    if size < 1:
        raise ValueError("size must be at least 1")
    chunk: list[T] = []
    for item in items:
        chunk.append(item)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk


def sliding_window[T](items: Iterable[T], width: int) -> Iterator[tuple[T, ...]]:
    if width < 1:
        raise ValueError("width must be at least 1")
    window: deque[T] = deque(maxlen=width)
    for item in items:
        window.append(item)
        if len(window) == width:
            yield tuple(window)
